public int minInsertions(String s) {
    int open = 0;
    int insertions = 0;

    for (char c : s.toCharArray()) {
        if (c == '(') {
            open++;
        } else {
            if (open > 0) {
                open--;
            } else {
                insertions++;
            }
            // Check for "))"
            if (c == ')' && s.indexOf("))", s.indexOf(c)) != -1) {
                c = s.charAt(s.indexOf(c) + 1);
                if (open > 0) {
                    open--;
                } else {
                    insertions++;
                }
            }
        }
    }

    // Add remaining open parentheses
    insertions += open * 2;

    return insertions;
}

